          "chinese_name": "订单分析与可视化",
          "description": "对订单数据进行分组、聚合、时间分桶、趋势与可视化分析，图表类型由参数显式指定。",
          "category": "analysis",
          "enabled": true,
          "source": "internal_service",
          "inputSchema": {
            "type": "object",
            "properties": {
              "customer_name": {
                "type": "string",
                "description": "客户名称，可选，用于按照客户名称模糊匹配",
                "label": "客户名称，可选，用于按照客户名称模糊匹配"
              },
              "order_code": {
                "type": "string",
                "description": "订单编号（对应数据库字段 code），可选，用于精确匹配订单编号",
                "examples": [
                  "20250609LSFACTC0260753",
                  "20250604LSFACTC0013447"
                ],
                "label": "订单编号（对应数据库字段 code），可选，用于精确匹配订单编号"
              },
              "status": {
                "type": "string",
                "description": "订单状态，可选，支持中文状态名称或状态编码（整数/整数字符串）。支持的状态：待提交(1)、待发送(6)、待确认(2)、已确认(3)、执行中(4)、已完成(5)、已作废(-1)",
                "enum": [
                  {
                    "key": "待提交",
                    "label": "待提交"
                  },
                  {
                    "key": "待发送",
                    "label": "待发送"
                  },
                  {
                    "key": "待确认",
                    "label": "待确认"
                  },
                  {
                    "key": "已确认",
                    "label": "已确认"
                  },
                  {
                    "key": "执行中",
                    "label": "执行中"
                  },
                  {
                    "key": "已完成",
                    "label": "已完成"
                  },
                  {
                    "key": "已作废",
                    "label": "已作废"
                  }
                ],
                "examples": [
                  "已完成",
                  "5"
                ],
                "label": "订单状态，可选，支持中文状态名称或状态编码（整数/整数字符串）。支持的状态：待提交(1)、待发送(6)、待确认(2)、已确认(3)、执行中(4)、已完成(5)、已作废(-1)"
              },
              "time_start": {
                "type": "string",
                "description": "开始时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-01T00:00:00Z），并包含边界",
                "examples": [
                  "2025-06-01",
                  "2025-06-01T00:00:00Z"
                ],
                "label": "开始时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-01T00:00:00Z），并包含边界"
              },
              "time_end": {
                "type": "string",
                "description": "结束时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-30T23:59:59Z），并不包含边界",
                "examples": [
                  "2025-06-30",
                  "2025-06-30T23:59:59Z"
                ],
                "label": "结束时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-30T23:59:59Z），并不包含边界"
              },
              "group_by": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "分组字段，可选，指定需要分组的列。字段名需使用数据库实际字段名，详见字段示例文档",
                "examples": [
                  [
                    "status"
                  ],
                  [
                    "customer_name",
                    "status"
                  ]
                ],
                "label": "分组字段，可选，指定需要分组的列。字段名需使用数据库实际字段名，详见字段示例文档"
              },
              "aggregations": {
                "type": "object",
                "description": "聚合定义，可选，配置字段与聚合方式映射。格式：{\"字段名\": \"聚合类型\"}，其中字段名为数据库实际字段名，聚合类型为 sum/count/avg/max/min 之一。示例：{\"code\": \"count\", \"price\": \"sum\"}。注意：订单编号字段名为 code，不是 order_id",
                "additionalProperties": {
                  "type": "string",
                  "enum": [
                    {
                      "key": "sum",
                      "label": "求和"
                    },
                    {
                      "key": "count",
                      "label": "计数"
                    },
                    {
                      "key": "avg",
                      "label": "平均值"
                    },
                    {
                      "key": "max",
                      "label": "最大值"
                    },
                    {
                      "key": "min",
                      "label": "最小值"
                    }
                  ]
                },
                "examples": [
                  {
                    "code": "count"
                  },
                  {
                    "code": "count",
                    "price": "sum"
                  },
                  {
                    "price": "avg",
                    "team_size": "max"
                  }
                ],
                "label": "聚合定义，可选，配置字段与聚合方式映射。格式：{\"字段名\": \"聚合类型\"}，其中字段名为数据库实际字段名，聚合类型为 sum/count/avg/max/min 之一。示例：{\"code\": \"count\", \"price\": \"sum\"}。注意：订单编号字段名为 code，不是 order_id"
              },
              "time_bucket": {
                "type": "object",
                "description": "时间分桶，可选，用于按周期聚合时间字段",
                "properties": {
                  "period": {
                    "type": "string",
                    "enum": [
                      {
                        "key": "day",
                        "label": "按日"
                      },
                      {
                        "key": "week",
                        "label": "按周"
                      },
                      {
                        "key": "month",
                        "label": "按月"
                      },
                      {
                        "key": "quarter",
                        "label": "按季度"
                      },
                      {
                        "key": "year",
                        "label": "按年"
                      }
                    ]
                  },
                  "aggregations": {
                    "type": "object",
                    "description": "时间分桶内的聚合定义，格式：{\"字段名\": \"聚合类型\"}，详见主 aggregations 字段说明",
                    "additionalProperties": {
                      "type": "string",
                      "enum": [
                        {
                          "key": "sum",
                          "label": "求和"
                        },
                        {
                          "key": "count",
                          "label": "计数"
                        },
                        {
                          "key": "avg",
                          "label": "平均值"
                        },
                        {
                          "key": "max",
                          "label": "最大值"
                        },
                        {
                          "key": "min",
                          "label": "最小值"
                        }
                      ]
                    },
                    "examples": [
                      {
                        "code": "count"
                      },
                      {
                        "price": "sum"
                      }
                    ]
                  },
                  "time_field": {
                    "type": "string",
                    "description": "时间字段，可选，用于时间分桶的基准列，与查询条件的 time_start/time_end 相互独立。字段名需使用数据库实际字段名，详见字段示例文档",
                    "default": "create_time",
                    "examples": [
                      "create_time",
                      "start_date",
                      "confirm_time",
                      "done_time"
                    ]
                  }
                },
                "label": "时间分桶，可选，用于按周期聚合时间字段"
              },
              "time_interval": {
                "type": "object",
                "description": "时长计算，可选，用于计算起止字段间时长",
                "properties": {
                  "start_field": {
                    "type": "string"
                  },
                  "end_field": {
                    "type": "string"
                  },
                  "unit": {
                    "type": "string",
                    "enum": [
                      {
                        "key": "seconds",
                        "label": "秒"
                      },
                      {
                        "key": "minutes",
                        "label": "分钟"
                      },
                      {
                        "key": "hours",
                        "label": "小时"
                      },
                      {
                        "key": "days",
                        "label": "天"
                      }
                    ]
                  },
                  "distribution_buckets": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  }
                },
                "label": "时长计算，可选，用于计算起止字段间时长"
              },
              "trend": {
                "type": "object",
                "description": "趋势分析，可选，用于检测指标趋势",
                "properties": {
                  "metric_field": {
                    "type": "string",
                    "description": "趋势分析的指标字段，必须是数值型字段（如 amount、price、team_size 等），不支持分类字段（如 status）。字段名需使用数据库实际字段名，详见字段示例文档",
                    "examples": [
                      "amount",
                      "price",
                      "team_size",
                      "code"
                    ]
                  },
                  "trend_type": {
                    "type": "string",
                    "enum": [
                      {
                        "key": "linear",
                        "label": "线性趋势"
                      },
                      {
                        "key": "growth_rate",
                        "label": "增长率"
                      },
                      {
                        "key": "moving_average",
                        "label": "移动平均"
                      }
                    ]
                  },
                  "time_field": {
                    "type": "string",
                    "description": "时间字段，可选，用于趋势分析的基准列，若未显式指定则尝试使用 time_period，缺失时回退 create_time。字段名需使用数据库实际字段名，详见字段示例文档",
                    "default": "time_period",
                    "examples": [
                      "time_period",
                      "create_time",
                      "start_date"
                    ]
                  }
                },
                "label": "趋势分析，可选，用于检测指标趋势"
              },
              "chart_config": {
                "type": "object",
                "description": "可视化配置，必填，用于定义输出结构",
                "properties": {
                  "output_format": {
                    "type": "string",
                    "enum": [
                      {
                        "key": "table",
                        "label": "数据表"
                      },
                      {
                        "key": "line_chart",
                        "label": "折线图"
                      },
                      {
                        "key": "bar_chart",
                        "label": "柱状图"
                      },
                      {
                        "key": "pie_chart",
                        "label": "饼图"
                      },
                      {
                        "key": "distribution_chart",
                        "label": "分布图"
                      }
                    ],
                    "default": "table"
                  },
                  "x_field": {
                    "type": "string"
                  },
                  "y_field": {
                    "type": "string"
                  },
                  "series_field": {
                    "type": "string"
                  },
                  "columns": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "field": {
                          "type": "string"
                        },
                        "label": {
                          "type": "string"
                        }
                      },
                      "required": [
                        "field",
                        "label"
                      ]
                    },
                    "description": "表格列，可选，仅当 output_format=table 时使用"
                  },
                  "pagination": {
                    "type": "object",
                    "properties": {
                      "page_size": {
                        "type": "integer",
                        "minimum": 1,
                        "default": 20
                      },
                      "current_page": {
                        "type": "integer",
                        "minimum": 1,
                        "default": 1
                      }
                    }
                  },
                  "distribution_field": {
                    "type": "string",
                    "description": "分布字段，条件必填（当 output_format=distribution_chart 时），填写需要做分布分析的数值字段如 amount 或 duration"
                  },
                  "chart_type": {
                    "type": "string",
                    "description": "分布图类型，可选，用于指定 distribution_chart 的展示样式",
                    "enum": [
                      {
                        "key": "histogram",
                        "label": "直方图"
                      },
                      {
                        "key": "bar",
                        "label": "条形图"
                      },
                      {
                        "key": "boxplot",
                        "label": "箱线图"
                      }
                    ]
                  }
                },
                "required": [
                  "output_format"
                ],
                "label": "可视化配置，必填，用于定义输出结构"
              }
            }
          }
        },
