   {\n                  \"key\": \"min\",\n                  \"label\": \"最小值\"\n                }\n              ]\n            },\n            \"examples\": [\n              {\n                \"code\": \"count\"\n              },\n              {\n                \"price\": \"sum\"\n              }\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于时间分桶的基准列，与查询条件的 time_start/time_end 相互独立。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"create_time\",\n            \"examples\": [\n              \"create_time\",\n              \"start_date\",\n              \"confirm_time\",\n              \"done_time\"\n            ]\n          }\n        },\n        \"label\": \"时间分桶，可选，用于按周期聚合时间字段\"\n      },\n      \"time_interval\": {\n        \"type\": \"object\",\n        \"description\": \"时长计算，可选，用于计算起止字段间时长\",\n        \"properties\": {\n          \"start_field\": {\n            \"type\": \"string\"\n          },\n          \"end_field\": {\n            \"type\": \"string\"\n          },\n          \"unit\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"seconds\",\n                \"label\": \"秒\"\n              },\n              {\n                \"key\": \"minutes\",\n                \"label\": \"分钟\"\n              },\n              {\n                \"key\": \"hours\",\n                \"label\": \"小时\"\n              },\n              {\n                \"key\": \"days\",\n                \"label\": \"天\"\n              }\n            ]\n          },\n          \"distribution_buckets\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"string\"\n            }\n          }\n        },\n        \"label\": \"时长计算，可选，用于计算起止字段间时长\"\n      },\n      \"trend\": {\n        \"type\": \"object\",\n        \"description\": \"趋势分析，可选，用于检测指标趋势\",\n        \"properties\": {\n          \"metric_field\": {\n            \"type\": \"string\",\n            \"description\": \"趋势分析的指标字段，必须是数值型字段（如 amount、price、team_size 等），不支持分类字段（如 status）。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"examples\": [\n              \"amount\",\n              \"price\",\n              \"team_size\",\n              \"code\"\n            ]\n          },\n          \"trend_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"linear\",\n                \"label\": \"线性趋势\"\n              },\n              {\n                \"key\": \"growth_rate\",\n                \"label\": \"增长率\"\n              },\n              {\n                \"key\": \"moving_average\",\n                \"label\": \"移动平均\"\n              }\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于趋势分析的基准列，若未显式指定则尝试使用 time_period，缺失时回退 create_time。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"time_period\",\n            \"examples\": [\n              \"time_period\",\n              \"create_time\",\n              \"start_date\"\n            ]\n          }\n        },\n        \"label\": \"趋势分析，可选，用于检测指标趋势\"\n      },\n      \"chart_config\": {\n        \"type\": \"object\",\n        \"description\": \"可视化配置，必填，用于定义输出结构\",\n        \"properties\": {\n          \"output_format\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"table\",\n                \"label\": \"数据表\"\n              },\n              {\n                \"key\": \"line_chart\",\n                \"label\": \"折线图\"\n              },\n              {\n                \"key\": \"bar_chart\",\n                \"label\": \"柱状图\"\n              },\n              {\n                \"key\": \"pie_chart\",\n                \"label\": \"饼图\"\n              },\n              {\n                \"key\": \"distribution_chart\",\n                \"label\": \"分布图\"\n              }\n            ],\n            \"default\": \"table\"\n          },\n          \"x_field\": {\n            \"type\": \"string\"\n          },\n          \"y_field\": {\n            \"type\": \"string\"\n          },\n          \"series_field\": {\n            \"type\": \"string\"\n          },\n          \"columns\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"object\",\n              \"properties\": {\n                \"field\": {\n                  \"type\": \"string\"\n                },\n                \"label\": {\n                  \"type\": \"string\"\n                }\n              },\n              \"required\": [\n                \"field\",\n                \"label\"\n              ]\n            },\n            \"description\": \"表格列，可选，仅当 output_format=table 时使用\"\n          },\n          \"pagination\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"page_size\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"default\": 20\n              },\n              \"current_page\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"default\": 1\n              }\n            }\n          },\n          \"distribution_field\": {\n            \"type\": \"string\",\n            \"description\": \"分布字段，条件必填（当 output_format=distribution_chart 时），填写需要做分布分析的数值字段如 amount 或 duration\"\n          },\n          \"chart_type\": {\n            \"type\": \"string\",\n            \"description\": \"分布图类型，可选，用于指定 distribution_chart 的展示样式\",\n            \"enum\": [\n              {\n                \"key\": \"histogram\",\n                \"label\": \"直方图\"\n              },\n              {\n                \"key\": \"bar\",\n                \"label\": \"条形图\"\n              },\n              {\n                \"key\": \"boxplot\",\n                \"label\": \"箱线图\"\n            