ic_field\": {\n            \"type\": \"string\",\n            \"description\": \"趋势分析的指标字段，必须是数值型字段（如 amount、price、team_size 等），不支持分类字段（如 status）。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"examples\": [\n              \"amount\",\n              \"price\",\n              \"team_size\",\n              \"code\"\n            ]\n          },\n          \"trend_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"linear\",\n                \"label\": \"线性趋势\"\n              },\n              {\n                \"key\": \"growth_rate\",\n                \"label\": \"增长率\"\n              },\n              {\n                \"key\": \"moving_average\",\n                \"label\": \"移动平均\"\n              }\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于趋势分析的基准列，若未显式指定则尝试使用 time_period，缺失时回退 create_time。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"time_period\",\n            \"examples\": [\n              \"time_period\",\n              \"create_time\",\n              \"start_date\"\n            ]\n          }\n        },\n        \"label\": \"趋势分析，可选，用于检测指标趋势\"\n      },\n      \"chart_config\": {\n        \"type\": \"object\",\n        \"description\": \"可视化配置，必填，用于定义输出结构\",\n        \"properties\": {\n          \"output_format\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"table\",\n                \"label\": \"数据表\"\n              },\n              {\n                \"key\": \"line_chart\",\n                \"label\": \"折线图\"\n              },\n              {\n                \"key\": \"bar_chart\",\n                \"label\": \"柱状图\"\n              },\n              {\n                \"key\": \"pie_chart\",\n                \"label\": \"饼图\"\n              },\n              {\n                \"key\": \"distribution_chart\",\n                \"label\