配置字段与聚合方式映射。格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，聚合类型为 sum/count/avg/max/min 之一\",\n        \"additionalProperties\": {\n          \"type\": \"string\"\n        },\n        \"examples\": [\n          {\n            \"total_price\": \"sum\",\n            \"team_size\": \"sum\",\n            \"id\": \"count\"\n          },\n          {\n            \"total_income\": \"sum\",\n            \"id\": \"count\"\n          }\n        ],\n        \"label\": \"聚合定义，可选，配置字段与聚合方式映射。格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，聚合类型为 sum/count/avg/max/min 之一\"\n      },\n      \"time_bucket\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"period\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"day\",\n              \"week\",\n              \"month\",\n              \"quarter\",\n              \"year\"\n            ]\n          },\n          \"aggregations\": {\n            \"type\": \"object\",\n            \"description\": \"时间分桶内的聚合定义，格式：{\\\"字段名\\\": \\\"聚合类型\\\"}\",\n            \"additionalProperties\": {\n              \"type\": \"string\"\n            }\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"default\": \"start_time\"\n          }\n        },\n        \"label\": \"time_bucket\"\n      },\n      \"trend\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"metric_field\": {\n            \"type\": \"string\",\n            \"description\": \"趋势分析的指标字段，必须是数值型字段\",\n            \"examples\": [\n              \"total_price\",\n              \"team_size\"\n            ]\n          },\n          \"trend_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"linear\",\n              \"growth_rate\",\n              \"moving_average\"\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"default\": \"time_period\"\n          }\n        },\n        \"label\": \"trend\"\n      },\n      \"