          "full_json": "{\n  \"name\": \"analyze_customers\",\n  \"chinese_name\": \"客户统计分析\",\n  \"description\": \"对客户数据进行分组、聚合、时间分桶、趋势分析与可视化，支持按客户类型、是否协议客户、状态等维度统计。\",\n  \"category\": \"analysis\",\n  \"enabled\": true,\n  \"source\": \"internal_service\",\n  \"inputSchema\": {\n    \"type\": \"object\",\n    \"properties\": {\n      \"customer_name\": {\n        \"type\": \"string\",\n        \"label\": \"customer_name\"\n      },\n      \"customer_type\": {\n        \"type\": \"string\",\n        \"label\": \"customer_type\"\n      },\n      \"is_agreement\": {\n        \"type\": \"integer\",\n        \"label\": \"is_agreement\"\n      },\n      \"status\": {\n        \"type\": \"integer\",\n        \"label\": \"status\"\n      },\n      \"time_start\": {\n        \"type\": \"string\",\n        \"description\": \"起始时间，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串\",\n        \"label\": \"起始时间，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串\"\n      },\n      \"time_end\": {\n        \"type\": \"string\",\n        \"description\": \"结束时间，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串\",\n        \"label\": \"结束时间，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串\"\n      },\n      \"group_by\": {\n        \"type\": \"array\",\n        \"items\": {\n          \"type\": \"string\"\n        },\n        \"description\": \"分组字段，可选，指定需要分组的列。字段名需使用数据库实际字段名，详见字段示例文档\",\n        \"examples\": [\n          [\n            \"status\"\n          ],\n          [\n            \"customer_type\",\n            \"status\"\n          ]\n        ],\n        \"label\": \"分组字段，可选，指定需要分组的列。字段名需使用数据库实际字段名，详见字段示例文档\"\n      },\n      \"aggregations\": {\n        \"type\": \"object\",\n        \"description\": \"聚合定义，可选，配置字段与聚合方式映射。格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，其中字段名为数据库实际字段名，聚合类型为 sum/count/avg/max/min 之一。示例：{\\\"customer_id\\\": \\\"count\\\", \\\"amount\\\": \\\"sum\\\"}\",\n        \"additionalProperties\": {\n          \"type\": \"string\"\n        },\n        \"examples\": [\n          {\n            \"customer_id\": \"count\"\n          },\n          {\n            \"customer_id\": \"count\",\n            \"amount\": \"sum\"\n          }\n        ],\n        \"label\": \"聚合定义，可选，配置字段与聚合方式映射。格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，其中字段名为数据库实际字段名，聚合类型为 sum/count/avg/max/min 之一。示例：{\\\"customer_id\\\": \\\"count\\\", \\\"amount\\\": \\\"sum\\\"}\"\n      },\n      \"time_bucket\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"period\": {\n            \"type\": \"string\"\n          },\n          \"aggregations\": {\n            \"type\": \"object\",\n            \"description\": \"时间分桶内的聚合定义，格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，详见主 aggregations 字段说明\",\n            \"additionalProperties\": {\n              \"type\": \"string\"\n            },\n            \"examples\": [\n              {\n                \"agreement_no\": \"count\"\n              },\n              {\n                \"amount\": \"sum\"\n              }\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于时间分桶的基准列。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"create_time\",\n            \"examples\": [\n              \"create_time\",\n              \"sign_date\",\n              \"valid_from_date\"\n            ]\n          }\n        },\n        \"label\": \"time_bucket\"\n      },\n      \"trend\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"metric_field\": {\n            \"type\": \"string\",\n            \"description\": \"趋势分析的指标字段，必须是数值型字段，不支持分类字段。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"examples\": [\n              \"count\",\n              \"amount\",\n              \"visitor_count\"\n            ]\n          },\n          \"trend_type\": {\n            \"type\": \"string\"\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于趋势分析的基准列。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"time_period\",\n            \"examples\": [\n              \"time_period\",\n              \"create_time\"\n            ]\n          }\n        },\n        \"label\": \"trend\"\n      },\n      \"chart_config\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"output_format\": {\n            \"type\": \"string\",\n            \"default\": \"table\"\n          }\n        },\n        \"required\": [\n          \"output_format\"\n        ],\n        \"label\": \"chart_config\"\n      }\n    }\n  }\n}",
