                  "type": "string"
                },
                "examples": [
                  {
                    "total_proceeds": "sum"
                  },
                  {
                    "ticket_proceeds": "sum",
                    "traffic_proceeds": "sum"
                  }
                ],
                "label": "聚合定义，可选，配置字段与聚合方式映射。格式：{\"字段名\": \"聚合类型\"}，聚合类型为 sum/count/avg/max/min 之一"
