                    "additionalProperties": {
                      "type": "string"
                    }
                  },
                  "time_field": {
                    "type": "string",
                    "default": "order_date"
                  }
                },
                "label": "time_bucket"
              },
              "trend": {
                "type": "object",
                "properties": {
                  "metric_field": {
                    "type": "string",
