                  },
                  {
                    "key": "待发送",
                    "label": "待发送"
                  },
                  {
                    "key": "待确认",
                    "label": "待确认"
                  },
                  {
                    "key": "已确认",
                    "label": "已确认"
                  },
                  {
                    "key": "执行中",
                    "label": "执行中"
                  },
                  {
                    "key": "已完成",
                    "label": "已完成"
                  },
                  {
                    "key": "已作废",
                    "label": "已作废"
                  }
                ],
                "examples": [
                  "已完成",
                  "5"
