                  "type": "string",
                  "enum": [
                    {
                      "key": "sum",
                      "label": "求和"
                    },
                    {
                      "key": "count",
                      "label": "计数"
                    },
                    {
                      "key": "avg",
                      "label": "平均值"
                    },
                    {
                      "key": "max",
                      "label": "最大值"
                    },
                    {
                      "key": "min",
                      "label": "最小值"
                    }
                  ]
                },
                "examples": [
                  {
                    "code": "count"
                  },
                  {
                    "code": "count",
                    "price": "sum"
                  },
                  {
                    "price": "avg",
                    "team_size": "max"
                  }
                ],
