                      {
                        "key": "week",
                        "label": "按周"
                      },
                      {
                        "key": "month",
                        "label": "按月"
                      },
                      {
                        "key": "quarter",
                        "label": "按季度"
                      },
                      {
                        "key": "year",
                        "label": "按年"
                      }
