                          "key": "count",
                          "label": "计数"
                        },
                        {
                          "key": "avg",
                          "label": "平均值"
                        },
                        {
                          "key": "max",
                          "label": "最大值"
                        },
                        {
                          "key": "min",
                          "label": "最小值"
