                  "output_format": {
                    "type": "string",
                    "enum": [
                      {
                        "key": "table",
                        "label": "数据表"
                      },
                      {
                        "key": "line_chart",
                        "label": "折线图"
                      },
                      {
                        "key": "bar_chart",
                        "label": "柱状图"
                      },
                      {
                        "key": "pie_chart",
                        "label": "饼图"
                      },
                      {
                        "key": "distribution_chart",
                        "label": "分布图"
                      }
