                  "x_field": {
                    "type": "string"
                  },
                  "y_field": {
                    "type": "string"
                  },
                  "series_field": {
                    "type": "string"
                  },
                  "columns": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "field": {
                          "type": "string"
                        },
                        "label": {
                          "type": "string"
                        }
                      },
                      "required": [
                        "field",
                        "label"
                      ]
