                      {
                        "key": "histogram",
                        "label": "直方图"
                      },
                      {
                        "key": "bar",
                        "label": "条形图"
                      },
                      {
                        "key": "boxplot",
                        "label": "箱线图"
                      }
                    ]
                  }
                },
                "required": [
                  "output_format"
                ],
                "label": "可视化配置，必填，用于定义输出结构"
              }
            }
          }
