00Z），并包含边界\",\n        \"examples\": [\n          \"2025-06-01\",\n          \"2025-06-01T00:00:00Z\"\n        ],\n        \"label\": \"开始时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-01T00:00:00Z），并包含边界\"\n      },\n      \"time_end\": {\n        \"type\": \"string\",\n        \"format\": \"date-time\",\n        \"description\": \"结束时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-30T23:59:59Z），并不包含边界\",\n        \"examples\": [\n          \"2025-06-30\",\n          \"2025-06-30T23:59:59Z\"\n        ],\n        \"label\": \"结束时间，可选，推荐格式 YYYY-MM-DD，也兼容完整 RFC3339 时间字符串（如 2025-06-30T23:59:59Z），并不包含边界\"\n      },\n      \"group_by\": {\n        \"type\": \"array\",\n        \"items\": {\n          \"type\": \"string\"\n        },\n        \"default\": [],\n        \"description\": \"分组字段，可选，指定需要分组的列。字段名需使用数据库实际字段名，详见字段示例文档\",\n        \"examples\": [\n          [\n            \"status\"\n          ],\n          [\n            \"customer_name\",\n            \"status\"\n          ]\n        ],\n        \"label\": \"分组字段，可选，指定需要分组的列。字段名需使用数据库实际字段名，详见字段示例文档\"\n      },\n      \"aggregations\": {\n        \"type\": \"object\",\n        \"description\": \"聚合定义，可选，配置字段与聚合方式映射。格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，其中字段名为数据库实际字段名，聚合类型为 sum/count/avg/max/min 之一。示例：{\\\"code\\\": \\\"count\\\", \\\"price\\\": \\\"sum\\\"}。注意：订单编号字段名为 code，不是 order_id\",\n        \"additionalProperties\": {\n          \"type\": \"string\",\n          \"enum\": [\n            {\n              \"key\": \"sum\",\n              \"label\": \"求和\"\n            },\n            {\n              \"key\": \"count\",\n              \"label\": \"计数\"\n            },\n            {\n              \"key\": \"avg\",\n              \"label\": \"平均值\"\n            },\n            {\n              \"key\": \"max\",\n              \"label\": \"最大值\"\n            },\n            {\n              \"key\": \"min\",\n              \"label\": \"最小值\"\n            }\n          ]\n        },\n        \"examples\": [\n          {\n            \"code\": \"count\"\n          },\n          {\n            \"code\": \"count\",\n            \"price\": \"sum\"\n          },\n          {\n            \"price\": \"avg\",\n            \"team_size\": \"max\"\n          }\n        ],\n        \"label\": \"聚合定义，可选，配置字段与聚合方式映射。格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，其中字段名为数据库实际字段名，聚合类型为 sum/count/avg/max/min 之一。示例：{\\\"code\\\": \\\"count\\\", \\\"price\\\": \\\"sum\\\"}。注意：订单编号字段名为 code，不是 order_id\"\n      },\n      \"time_bucket\": {\n        \"type\": \"object\",\n        \"description\": \"时间分桶，可选，用于按周期聚合时间字段\",\n        \"properties\": {\n          \"period\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"day\",\n                \"label\": \"按日\"\n              },\n              {\n                \"key\": \"week\",\n                \"label\": \"按周\"\n              },\n              {\n                \"key\": \"month\",\n                \"label\": \"按月\"\n              },\n              {\n                \"key\": \"quarter\",\n                \"label\": \"按季度\"\n              },\n              {\n                \"key\": \"year\",\n                \"label\": \"按年\"\n              }\n            ]\n          },\n          \"aggregations\": {\n            \"type\": \"object\",\n            \"description\": \"时间分桶内的聚合定义，格式：{\\\"字段名\\\": \\\"聚合类型\\\"}，详见主 aggregations 字段说明\",\n            \"additionalProperties\": {\n              \"type\": \"string\",\n              \"enum\": [\n                {\n                  \"key\": \"sum\",\n                  \"label\": \"求和\"\n                },\n                {\n                  \"key\": \"count\",\n                  \"label\": \"计数\"\n                },\n                {\n                  \"key\": \"avg\",\n                  \"label\": \"平均值\"\n                },\n                {\n                  \"key\": \"max\",\n                  \"label\": \"最大值\"\n                },\n                {\n                  \"key\": \"min\",\n                  \"label\": \"最小值\"\n                }\n              ]\n            },\n            \"examples\": [\n              {\n                \"code\": \"count\"\n              },\n              {\n                \"price\": \"sum\"\n              }\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于时间分桶的基准列，与查询条件的 time_start/time_end 相互独立。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"create_time\",\n            \"examples\": [\n              \"create_time\",\n              \"start_date\",\n              \"confirm_time\",\n              \"done_time\"\n            ]\n          }\n        },\n        \"label\": \"时间分桶，可选，用于按周期聚合时间字段\"\n      },\n      \"time_interval\": {\n        \"type\": \"object\",\n        \"description\": \"时长计算，可选，用于计算起止字段间时长\",\n        \"properties\": {\n          \"start_field\": {\n            \"type\": \"string\"\n          },\n          \"end_field\": {\n            \"type\": \"string\"\n          },\n          \"unit\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"seconds\",\n                \"label\": \"秒\"\n              },\n              {\n                \"key\": \"minutes\",\n                \"label\": \"分钟\"\n              },\n              {\n                \"key\": \"hours\",\n                \"label\": \"小时\"\n              },\n              {\n                \"key\": \"days\",\n                \"label\": \"天\"\n              }\n            ]\n          },\n          \"distribution_buckets\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"string\"\n            }\n          }\n        },\n        \"label\": \"时长计算，可选，用于计算起止字段间时长\"\n      },\n      \"trend\": {\n        \"type\": \"object\",\n        \"description\": \"趋势分析，可选，用于检测指标趋势\",\n        \"properties\": {\n          \"metric_field\": {\n            \"type\": \"string\",\n            \"description\": \"趋势分析的指标字段，必须是数值型字段（如 amount、price、team_size 等），不支持分类字段（如 status）。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"examples\": [\n              \"amount\",\n              \"price\",\n              \"team_size\",\n              \"code\"\n            ]\n          },\n          \"trend_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"linear\",\n                \"label\": \"线性趋势\"\n              },\n              {\n                \"key\": \"growth_rate\",\n                \"label\": \"增长率\"\n              },\n              {\n                \"key\": \"moving_average\",\n                \"label\": \"移动平均\"\n              }\n            ]\n          },\n          \"time_field\": {\n            \"type\": \"string\",\n            \"description\": \"时间字段，可选，用于趋势分析的基准列，若未显式指定则尝试使用 time_period，缺失时回退 create_time。字段名需使用数据库实际字段名，详见字段示例文档\",\n            \"default\": \"time_period\",\n            \"examples\": [\n              \"time_period\",\n              \"create_time\",\n              \"start_date\"\n            ]\n          }\n        },\n        \"label\": \"趋势分析，可选，用于检测指标趋势\"\n      },\n      \"chart_config\": {\n        \"type\": \"object\",\n        \"description\": \"可视化配置，必填，用于定义输出结构\",\n        \"properties\": {\n          \"output_format\": {\n            \"type\": \"string\",\n            \"enum\": [\n              {\n                \"key\": \"table\",\n                \"label\": \"数据表\"\n              },\n              {\n                \"key\": \"line_chart\",\n                \"label\": \"折线图\"\n              },\n              {\n                \"key\": \"bar_chart\",\n                \"label\": \"柱状图\"\n              },\n              {\n                \"key\": \"pie_chart\",\n                \"label\": \"饼图\"\n              },\n              {\n                \"key\": \"distribution_chart\",\n                \"label\": \"分布图\"\n              }\n            ],\n            \"default\": \"table\"\n          },\n          \"x_field\": {\n            \"type\": \"string\"\n          },\n          \"y_field\": {\n            \"type\": \"string\"\n          },\n          \"series_field\": {\n            \"type\": \"string\"\n          },\n          \"columns\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"object\",\n              \"properties\": {\n                \"field\": {\n                  \"type\": \"string\"\n                },\n                \"label\": {\n                  \"type\": \"string\"\n                }\n              },\n              \"required\": [\n                \"field\",\n                \"label\"\n              ]\n            },\n            \"description\": \"表格列，可选，仅当 output_format=table 时使用\"\n          },\n          \"pagination\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"page_size\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"default\": 20\n              },\n              \"current_page\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"default\": 1\n              }\n            }\n          },\n          \"distribution_field\": {\n            \"type\": \"string\",\n            \"description\": \"分布字段，条件必填（当 output_format=distribution_chart 时），填写需要做分布分析的数值字段如 amount 或 duration\"\n          },\n          \"chart_type\": {\n            \"type\": \"string\",\n            \"description\": \"分布图类型，可选，用于指定 distribution_chart 的展示样式\",\n            \"enum\": [\n              {\n                \"key\": \"histogram\",\n                \"label\": \"直方图\"\n              },\n              {\n                \"key\": \"bar\",\n                \"label\": \"条形图\"\n              },\n              {\n                \"key\": \"boxplot\",\n                \"label\": \"箱线图\"\n              }\n            ]\n          }\n        },\n        \"required\": [\n          \"output_format\"\n        ],\n        \"label\": \"可视化配置，必填，用于定义输出结构\"\n      }\n    }\n  }\n}",
